## Handoffs
→ ndv-diagnose (root cause) · src/age.js:3-4: `n < 0 || n > 150` is a no-op for `NaN`. Every input that makes `parseInt` return `NaN` (null, undefined, empty/whitespace string, non-numeric string, object, array, bare array, `Infinity`, `NaN`) silently bypasses the range check and returns `NaN` instead of throwing `RangeError`, directly violating the documented contract ("throws RangeError for anything else").
→ ndv-diagnose (root cause) · src/age.js:2: `parseInt` only consumes a leading numeric prefix and ignores trailing characters, so strings like `'25abc'`, `'0x1A'`, `'1e2'` parse successfully to a truncated in-range value instead of being rejected as malformed. The function never checks that the whole input string was consumed.
→ ndv-diagnose (root cause) · src/age.js:2: Passing a `Symbol` throws `TypeError` (from `parseInt`'s internal string coercion), not the contractually-promised `RangeError` — callers catching `RangeError` specifically will see an uncaught exception.
→ ndv-secure (vulnerability) · src/age.js:2: Conditional/low-confidence — because trailing characters are silently dropped, strings shaped like injection payloads (e.g. `'25; DROP TABLE users;'`) are accepted as valid ages rather than rejected. Not exploitable in this function alone, but if any caller assumes "parseAge succeeded" implies "the input was a clean integer string" and reuses the original string elsewhere (logging, display, a secondary query), that assumption is false. Worth a look at call sites.

## Tests for: `isAdult` in `src/age.js`

**Scenarios covered:**
- [ ] Boundary: age exactly 18 → spec says adult, must verify (**this exposes a source bug**)
- [ ] Boundary: age 17 (just under) → not adult
- [ ] Boundary: age 19 (just over) → adult
- [ ] Boundary: age 0
- [ ] Error: negative age (-1)
- [ ] Error: non-integer age (18.5, 17.999999)
- [ ] Error: null / undefined
- [ ] Error: NaN
- [ ] Error: wrong type — string, object, array, boolean
- [ ] Error: numeric-string type coercion ("19", "17")
- [ ] Boundary: extreme values (Infinity, -Infinity, Number.MAX_SAFE_INTEGER)
- [ ] Happy path: clearly adult age (e.g. 30), clearly minor age (e.g. 10)

Framework note: no existing test file for this module was found to establish convention, so this uses plain `node:test` + `node:assert/strict`, matching the framework named in the brief.

```js
// src/age.test.js
import { test, describe } from 'node:test'
import assert from 'node:assert/strict'
import { isAdult } from './age.js'

describe('isAdult', () => {
  describe('boundary conditions', () => {
    test('should return true when age is exactly 18 (spec: 18 or over is adult)', () => {
      // Arrange
      const age = 18
      // Act
      const result = isAdult(age)
      // Assert
      assert.equal(result, true, 'age 18 must be treated as adult per the stated correctness rule')
    })

    test('should return false when age is 17 (just under threshold)', () => {
      const age = 17
      const result = isAdult(age)
      assert.equal(result, false)
    })

    test('should return true when age is 19 (just over threshold)', () => {
      const age = 19
      const result = isAdult(age)
      assert.equal(result, true)
    })

    test('should return false when age is 0', () => {
      const age = 0
      const result = isAdult(age)
      assert.equal(result, false)
    })

    test('should return true when age is Number.MAX_SAFE_INTEGER', () => {
      const age = Number.MAX_SAFE_INTEGER
      const result = isAdult(age)
      assert.equal(result, true)
    })

    test('should return true when age is Infinity', () => {
      const age = Infinity
      const result = isAdult(age)
      assert.equal(result, true)
    })

    test('should return false when age is -Infinity', () => {
      const age = -Infinity
      const result = isAdult(age)
      assert.equal(result, false)
    })
  })

  describe('invalid / adversarial input', () => {
    test('should return false when age is negative (-1)', () => {
      const age = -1
      const result = isAdult(age)
      assert.equal(result, false)
    })

    test('should return true when age is a non-integer just over threshold (18.5)', () => {
      const age = 18.5
      const result = isAdult(age)
      assert.equal(result, true)
    })

    test('should return false when age is a non-integer just under threshold (17.999999)', () => {
      const age = 17.999999
      const result = isAdult(age)
      assert.equal(result, false)
    })

    test('should return false when age is null', () => {
      // null > 18 evaluates to false in JS (coerced to 0)
      const result = isAdult(null)
      assert.equal(result, false)
    })

    test('should return false when age is undefined', () => {
      // undefined > 18 evaluates to false (NaN comparison)
      const result = isAdult(undefined)
      assert.equal(result, false)
    })

    test('should return false when age is NaN', () => {
      const result = isAdult(NaN)
      assert.equal(result, false)
    })

    test('should coerce numeric string "19" to true (documents implicit coercion behavior)', () => {
      // No type guard exists in the source; JS `>` coerces strings to numbers.
      const result = isAdult('19')
      assert.equal(result, true)
    })

    test('should coerce numeric string "17" to false (documents implicit coercion behavior)', () => {
      const result = isAdult('17')
      assert.equal(result, false)
    })

    test('should return false when age is a non-numeric string', () => {
      const result = isAdult('eighteen')
      assert.equal(result, false)
    })

    test('should return false when age is an object', () => {
      // {} > 18 → NaN comparison → false
      const result = isAdult({})
      assert.equal(result, false)
    })

    test('should return false when age is an empty array', () => {
      // [] coerces to 0 via toString/valueOf → 0 > 18 → false
      const result = isAdult([])
      assert.equal(result, false)
    })

    test('should coerce array [19] to true (documents implicit coercion behavior)', () => {
      // [19].toString() → "19" → coerced to number 19
      const result = isAdult([19])
      assert.equal(result, true)
    })

    test('should treat boolean true as 1 (not adult)', () => {
      const result = isAdult(true)
      assert.equal(result, false)
    })
  })

  describe('happy path', () => {
    test('should return true when age is clearly an adult (30)', () => {
      const result = isAdult(30)
      assert.equal(result, true)
    })

    test('should return false when age is clearly a minor (10)', () => {
      const result = isAdult(10)
      assert.equal(result, false)
    })
  })
})
```

